import type {
  FailureCategory,
  FormatOptions,
  SummaryData,
  TestRecord,
} from './types';
import {
  buildDurationBar,
  buildHealthBar,
  escapeMarkdown,
  failureCategoryMeta,
  formatDuration,
  formatPassRate,
} from './utils';

const FOOTER =
  '_Generated by [playwright-summary-reporter](https://www.npmjs.com/package/playwright-summary-reporter)_';

/** Number of characters in the proportional health bar. */
const HEALTH_BAR_SEGMENTS = 12;

/** Number of segments in a relative duration bar. */
const DURATION_BAR_SEGMENTS = 10;

/**
 * Escapes a value used inside a Markdown table cell.
 *
 * This is the single place where pipe escaping happens — error messages arrive
 * here already collapsed to one line but *not* escaped, so escaping twice
 * would produce a stray double backslash.
 */
function cell(value: string): string {
  return escapeMarkdown(value.replace(/\r?\n/g, ' '));
}

/** Builds a GitHub-Flavored Markdown table from a header row and body rows. */
function table(headers: string[], rows: string[][]): string {
  const lines: string[] = [];

  lines.push(`| ${headers.join(' | ')} |`);
  lines.push(`| ${headers.map(() => '---').join(' | ')} |`);

  for (const row of rows) {
    lines.push(`| ${row.join(' | ')} |`);
  }

  return lines.join('\n');
}

/** The display title of a test. */
export function testTitle(record: TestRecord): string {
  return record.title;
}

/** Wraps content in a collapsible `<details>` accordion. */
function accordion(summary: string, content: string): string {
  return ['<details>', `<summary>${summary}</summary>`, '', content, '</details>'].join('\n');
}

/**
 * The top status card.
 *
 * A fully green run gets a green `[!TIP]` alert; anything else gets a red
 * `[!CAUTION]` alert. The card carries the headline status, the pass rate and
 * the full result breakdown, plus the proportional health bar.
 */
function renderAlertCard(data: SummaryData): string {
  const allGreen = data.failed === 0 && data.flaky === 0 && data.timedOut === 0;
  const marker = allGreen ? '> [!TIP]' : '> [!CAUTION]';

  const healthBar = buildHealthBar(
    {
      passed: data.passed,
      failed: data.failed,
      flaky: data.flaky,
      skipped: data.skipped,
    },
    HEALTH_BAR_SEGMENTS,
  );

  const statusEmoji = allGreen ? '✅' : '❌';
  const statusWord = allGreen ? 'PASSED' : 'FAILED';

  const lines = [
    marker,
    '>',
    `> ### ${statusEmoji} ${statusWord} — ${formatPassRate(data.passRate)} pass rate`,
    '>',
    `> \`${healthBar}\` &nbsp; **Health Bar**`,
    '>',
    `> ✅ **Passed:** ${data.passed} &nbsp;•&nbsp; ❌ **Failed:** ${data.failed} &nbsp;•&nbsp; ⚠️ **Flaky:** ${data.flaky} &nbsp;•&nbsp; ⏭️ **Skipped:** ${data.skipped}`,
    '>',
    `> 📊 **Total:** ${data.total} &nbsp;•&nbsp; ⏱️ **Duration:** ${formatDuration(data.duration)}`,
  ];

  if (data.timedOut > 0) {
    lines.push('>');
    lines.push(`> ⏱️ **Timed Out:** ${data.timedOut} (counted within Failed)`);
  }

  return lines.join('\n');
}

/**
 * The KPI strip.
 *
 * A single wide table where every metric is a bold, high-contrast number with
 * an emoji label — the "at a glance" row of the dashboard.
 */
function renderKpiTable(data: SummaryData): string {
  const rows = [
    ['✅ Passed', `**${data.passed}**`],
    ['❌ Failed', `**${data.failed}**`],
    ['⚠️ Flaky', `**${data.flaky}**`],
    ['⏭️ Skipped', `**${data.skipped}**`],
    ['📊 Total', `**${data.total}**`],
    ['🎯 Pass Rate', `**${formatPassRate(data.passRate)}**`],
    ['⏱️ Duration', `**${formatDuration(data.duration)}**`],
  ];

  return table(['Metric', 'Value'], rows);
}

/**
 * The Mermaid pie chart of the result distribution.
 *
 * Only non-zero categories are rendered — a zero-value slice adds noise and
 * still consumes legend space.
 */
function renderMermaidChart(data: SummaryData): string {
  const slices: string[] = [];

  if (data.passed > 0) {
    slices.push(`    "Passed" : ${data.passed}`);
  }

  if (data.failed > 0) {
    slices.push(`    "Failed" : ${data.failed}`);
  }

  if (data.flaky > 0) {
    slices.push(`    "Flaky" : ${data.flaky}`);
  }

  if (data.skipped > 0) {
    slices.push(`    "Skipped" : ${data.skipped}`);
  }

  if (slices.length === 0) {
    return '';
  }

  return [
    '```mermaid',
    'pie showData',
    '    title Test Results Distribution',
    ...slices,
    '```',
  ].join('\n');
}

/** The badge cell for a failed test, e.g. `⏱️ Timeout`. */
function failureBadge(record: TestRecord): string {
  const category: FailureCategory = record.category ?? 'runtime';
  const meta = failureCategoryMeta(category);

  return `${meta.badge} ${meta.label}`;
}

/** Renders the "Failed Tests" table, or `undefined` when there are no failures. */
function renderFailedTests(tests: TestRecord[]): string | undefined {
  const failed = tests.filter((t) => t.outcome === 'failed' || t.outcome === 'timedOut');

  if (failed.length === 0) {
    return undefined;
  }

  const rows = failed.map((t) => [
    cell(failureBadge(t)),
    cell(testTitle(t)),
    cell(t.project),
    cell(`${t.file}:${t.line}`),
    cell(t.error ?? '—'),
  ]);

  return ['### ❌ Failed Tests', '', table(['Type', 'Test', 'Project', 'Location', 'Error'], rows)].join('\n');
}

/**
 * Builds the copy-ready "re-run only failed tests" command.
 *
 * Each failing test contributes `file:line`, which is Playwright's native way
 * of targeting a single test. Tests are de-duplicated so a file with three
 * failures contributes one entry per distinct line.
 */
export function buildRerunCommand(tests: TestRecord[]): string {
  const failed = tests.filter((t) => t.outcome === 'failed' || t.outcome === 'timedOut');

  if (failed.length === 0) {
    return '';
  }

  const targets: string[] = [];
  const seen = new Set<string>();

  for (const test of failed) {
    const target = `${test.file}:${test.line}`;
    if (!seen.has(target)) {
      seen.add(target);
      targets.push(target);
    }
  }

  return `npx playwright test ${targets.join(' ')}`;
}

/** Renders the re-run command block. */
function renderRerunBlock(tests: TestRecord[]): string | undefined {
  const command = buildRerunCommand(tests);

  if (!command) {
    return undefined;
  }

  return [
    '#### 🔁 Re-run only failed tests',
    '',
    '```bash',
    command,
    '```',
  ].join('\n');
}

/** Renders the "Flaky Tests" table, or `undefined` when there are no flaky tests. */
function renderFlakyTests(tests: TestRecord[]): string | undefined {
  const flaky = tests.filter((t) => t.outcome === 'flaky');

  if (flaky.length === 0) {
    return undefined;
  }

  const rows = flaky.map((t) => [
    cell(testTitle(t)),
    cell(t.project),
    String(t.retries),
    formatDuration(t.duration),
    cell(`${t.file}:${t.line}`),
  ]);

  return [
    '### ⚠️ Flaky Tests',
    '',
    table(['Test', 'Project', 'Retries', 'Duration', 'Location'], rows),
  ].join('\n');
}

/**
 * Builds the collapsible AI debugging prompt.
 *
 * The prompt bundles every failure with its location and error message so an
 * assistant can triage without needing to re-read the run.
 */
export function buildAiPrompt(tests: TestRecord[], title: string): string {
  const failed = tests.filter((t) => t.outcome === 'failed' || t.outcome === 'timedOut');

  if (failed.length === 0) {
    return '';
  }

  const lines: string[] = [
    `You are triaging a failing Playwright test run ("${title}").`,
    '',
    'For each failing test below:',
    '1. Identify the most likely root cause of the failure.',
    '2. Explain what the assertion or locator actually observed.',
    '3. Propose a concrete, minimal fix to the test or the application code.',
    '4. Flag anything that looks like a race condition or an unstable locator.',
    '',
    '---',
    '',
  ];

  failed.forEach((test, index) => {
    const meta = failureCategoryMeta(test.category ?? 'runtime');

    lines.push(`### ${index + 1}. ${test.title}`);
    lines.push('');
    lines.push(`- **Category:** ${meta.badge} ${meta.label}`);
    lines.push(`- **Project:** ${test.project}`);
    lines.push(`- **Location:** ${test.file}:${test.line}`);
    lines.push(`- **Duration:** ${formatDuration(test.duration)}`);
    lines.push(`- **Retries:** ${test.retries}`);
    lines.push('- **Error:**');
    lines.push('');
    lines.push('```');
    lines.push(test.error ?? '(no error message captured)');
    lines.push('```');
    lines.push('');
  });

  lines.push('---');
  lines.push('');
  lines.push(
    'Please respond with a prioritised list of root causes and the exact code changes required to fix each failing test.',
  );

  return lines.join('\n');
}

/** Renders the AI debugging prompt accordion. */
function renderAiPrompt(tests: TestRecord[], title: string): string | undefined {
  const prompt = buildAiPrompt(tests, title);

  if (!prompt) {
    return undefined;
  }

  return accordion(
    '🤖 AI Debugging Prompt (click to copy for Copilot / Claude / Cursor)',
    ['```text', prompt, '```'].join('\n'),
  );
}

/**
 * Renders the "Slowest Tests" table.
 *
 * Each row carries a relative 10-segment bar so the spread between the
 * slowest and fastest test is readable at a glance.
 */
function renderSlowestTests(tests: TestRecord[], limit: number): string | undefined {
  if (limit <= 0) {
    return undefined;
  }

  const candidates = tests.filter((t) => t.outcome !== 'skipped');

  if (candidates.length === 0) {
    return undefined;
  }

  const slowest = [...candidates].sort((a, b) => b.duration - a.duration).slice(0, limit);
  const max = slowest.reduce((highest, t) => Math.max(highest, t.duration), 0);

  const rows = slowest.map((t) => [
    cell(testTitle(t)),
    cell(t.project),
    formatDuration(t.duration),
    `\`${buildDurationBar(t.duration, max, DURATION_BAR_SEGMENTS)}\``,
  ]);

  return [
    '### 🐢 Slowest Tests',
    '',
    table(['Test', 'Project', 'Duration', 'Relative'], rows),
  ].join('\n');
}

/** Renders the per-project breakdown table, or `undefined` when there are none. */
function renderProjectBreakdown(projects: SummaryData['projects']): string | undefined {
  if (projects.length === 0) {
    return undefined;
  }

  const rows = projects.map((p) => [
    cell(p.project),
    String(p.total),
    String(p.passed),
    String(p.failed),
    String(p.flaky),
    String(p.skipped),
    formatDuration(p.duration),
  ]);

  return [
    '### 📊 Project Breakdown',
    '',
    table(['Project', 'Total', 'Passed', 'Failed', 'Flaky', 'Skipped', 'Duration'], rows),
  ].join('\n');
}

/**
 * Renders the complete Markdown report.
 */
export function formatSummary(data: SummaryData, options?: FormatOptions): string {
  const showSlowestTests = options?.showSlowestTests ?? 5;
  const includeProjectBreakdown = options?.includeProjectBreakdown ?? true;
  const showFailedTests = options?.showFailedTests ?? true;
  const showFlakyTests = options?.showFlakyTests ?? true;
  const includeChart = options?.includeChart ?? true;
  const includeRerunCommand = options?.includeRerunCommand ?? true;
  const includeAiPrompt = options?.includeAiPrompt ?? true;
  const collapsibleDetails = options?.collapsibleDetails ?? false;

  const sections: string[] = [];

  // Header.
  sections.push(`## ${data.title}`);
  sections.push('');

  // Status alert card.
  sections.push(renderAlertCard(data));
  sections.push('');

  // KPI strip.
  sections.push(renderKpiTable(data));
  sections.push('');

  // Mermaid pie chart.
  if (includeChart) {
    const chart = renderMermaidChart(data);
    if (chart) {
      sections.push(chart);
      sections.push('');
    }
  }

  // Project breakdown.
  if (includeProjectBreakdown) {
    const breakdown = renderProjectBreakdown(data.projects);
    if (breakdown) {
      sections.push(breakdown);
      sections.push('');
    }
  }

  // Failed tests — always expanded so the failures are immediately visible.
  if (showFailedTests) {
    const failed = renderFailedTests(data.tests);
    if (failed) {
      sections.push(failed);
      sections.push('');

      if (includeRerunCommand) {
        const rerun = renderRerunBlock(data.tests);
        if (rerun) {
          sections.push(rerun);
          sections.push('');
        }
      }

      if (includeAiPrompt) {
        const prompt = renderAiPrompt(data.tests, data.title);
        if (prompt) {
          sections.push(prompt);
          sections.push('');
        }
      }
    }
  }

  // Flaky tests — always expanded.
  if (showFlakyTests) {
    const flaky = renderFlakyTests(data.tests);
    if (flaky) {
      sections.push(flaky);
      sections.push('');
    }
  }

  // Slowest tests.
  const slowest = renderSlowestTests(data.tests, showSlowestTests);
  if (slowest) {
    if (collapsibleDetails) {
      sections.push(accordion('🐢 Slowest Tests', slowest.replace(/^### /, '')));
    } else {
      sections.push(slowest);
    }
    sections.push('');
  }

  sections.push(FOOTER);

  return `${sections.join('\n').replace(/\n{3,}/g, '\n\n').trimEnd()}\n`;
}
